CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE app_user (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, full_name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('ADMIN','ENGINEER','OPERATOR','VIEWER')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE factory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, timezone text NOT NULL, status text NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE production_line (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), factory_id uuid NOT NULL REFERENCES factory(id), code text NOT NULL, name text NOT NULL, product text NOT NULL, status text NOT NULL DEFAULT 'RUNNING', UNIQUE(factory_id,code));
CREATE TABLE machine (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), factory_id uuid NOT NULL REFERENCES factory(id), line_id uuid NOT NULL REFERENCES production_line(id), code text UNIQUE NOT NULL, name text NOT NULL, machine_type text NOT NULL, status text NOT NULL DEFAULT 'RUNNING', health numeric(5,2) NOT NULL DEFAULT 98, failure_probability numeric(5,4) NOT NULL DEFAULT .02, rul_hours numeric(10,2) NOT NULL DEFAULT 2500, last_maintenance timestamptz NOT NULL DEFAULT now() - interval '15 days');
CREATE TABLE sensor (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), machine_id uuid NOT NULL REFERENCES machine(id), code text NOT NULL, kind text NOT NULL, unit text NOT NULL, UNIQUE(machine_id,code));
CREATE TABLE sensor_reading (id bigserial PRIMARY KEY, sensor_id uuid NOT NULL REFERENCES sensor(id), recorded_at timestamptz NOT NULL, value double precision NOT NULL);
CREATE INDEX ix_sensor_reading_sensor_time ON sensor_reading(sensor_id, recorded_at DESC);
CREATE TABLE production_metric (id bigserial PRIMARY KEY, factory_id uuid NOT NULL REFERENCES factory(id), line_id uuid REFERENCES production_line(id), recorded_at timestamptz NOT NULL, target integer NOT NULL, actual integer NOT NULL, throughput numeric(12,2) NOT NULL, cycle_time numeric(12,2) NOT NULL, downtime_minutes numeric(12,2) NOT NULL, oee numeric(6,3) NOT NULL, quality numeric(6,3) NOT NULL, scrap integer NOT NULL);
CREATE INDEX ix_prod_time ON production_metric(factory_id, recorded_at DESC);
CREATE TABLE maintenance_record (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), factory_id uuid NOT NULL REFERENCES factory(id), machine_id uuid NOT NULL REFERENCES machine(id), status text NOT NULL, priority text NOT NULL, technician text NOT NULL, scheduled_at timestamptz, completed_at timestamptz, notes text, ai_recommendation text);
CREATE TABLE failure_prediction (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), machine_id uuid NOT NULL REFERENCES machine(id), health_score numeric(5,2) NOT NULL, anomaly_score numeric(5,4) NOT NULL, failure_probability numeric(5,4) NOT NULL, rul_hours numeric(10,2), risk_level text NOT NULL, predicted_at timestamptz NOT NULL, model_version text NOT NULL, explanation text NOT NULL);
CREATE TABLE anomaly (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), machine_id uuid NOT NULL REFERENCES machine(id), sensor_kind text, score numeric(5,4) NOT NULL, description text NOT NULL, detected_at timestamptz NOT NULL);
CREATE TABLE quality_inspection (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), factory_id uuid NOT NULL REFERENCES factory(id), product_id text NOT NULL, result text NOT NULL, confidence numeric(5,4) NOT NULL, method text NOT NULL, model_version text NOT NULL, image_name text, inspected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quality_defect (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inspection_id uuid NOT NULL REFERENCES quality_inspection(id) ON DELETE CASCADE, category text NOT NULL, confidence numeric(5,4) NOT NULL);
CREATE TABLE energy_metric (id bigserial PRIMARY KEY, factory_id uuid NOT NULL REFERENCES factory(id), machine_id uuid REFERENCES machine(id), recorded_at timestamptz NOT NULL, kwh numeric(12,3) NOT NULL, energy_per_unit numeric(12,4) NOT NULL, peak_kw numeric(12,3) NOT NULL, cost numeric(12,4) NOT NULL, baseline numeric(12,3) NOT NULL, anomaly boolean NOT NULL DEFAULT false);
CREATE TABLE alert (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), factory_id uuid NOT NULL REFERENCES factory(id), machine_id uuid REFERENCES machine(id), severity text NOT NULL, status text NOT NULL, description text NOT NULL, evidence text NOT NULL, recommendation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz);
CREATE INDEX ix_alert_open ON alert(factory_id,status,created_at DESC);
CREATE TABLE ai_recommendation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), factory_id uuid NOT NULL REFERENCES factory(id), machine_id uuid REFERENCES machine(id), title text NOT NULL, insight text NOT NULL, evidence text NOT NULL, confidence numeric(5,4) NOT NULL, recommended_action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE autonomous_action (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), factory_id uuid NOT NULL REFERENCES factory(id), machine_id uuid REFERENCES machine(id), type text NOT NULL, state text NOT NULL, reason text NOT NULL, risk text NOT NULL, expected_outcome text NOT NULL, evidence text NOT NULL, actor text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), factory_id uuid NOT NULL REFERENCES factory(id), name text NOT NULL, mime_type text NOT NULL, status text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_chunk (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES document(id) ON DELETE CASCADE, chunk_index integer NOT NULL, content text NOT NULL, embedding jsonb, UNIQUE(document_id,chunk_index));
CREATE TABLE chat_session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_email text NOT NULL, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chat_message (id bigserial PRIMARY KEY, session_id uuid NOT NULL REFERENCES chat_session(id) ON DELETE CASCADE, role text NOT NULL, content text NOT NULL, sources jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log (id bigserial PRIMARY KEY, actor text NOT NULL, role text NOT NULL, action text NOT NULL, entity text NOT NULL, entity_id text, result text NOT NULL, request_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE system_event (id bigserial PRIMARY KEY, factory_id uuid NOT NULL REFERENCES factory(id), event_type text NOT NULL, machine_id uuid, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
